const outcomes=['Attend consistently','Join a small group','Serve in ministry','Give consistently','Invite a friend','Follow Jesus','Be baptized','Become a member','Make a disciple','Step into leadership','Pray consistently','Read Scripture','Strengthen family','Reconcile','Find healing','Discover SHAPE','Live on mission','Share faith','Develop leaders','Practice generosity'];
const sermons=[['Your Part Matters','Discover the Ministry God Designed You to Do','1 Corinthians 12:12–27','Serve in ministry','serving gifts volunteer'],['Better Together','Why No One Grows Alone','Hebrews 10:24–25','Join a small group','community groups belonging'],['Open Hands','Discovering the Freedom of Generosity','2 Corinthians 9:6–11','Give consistently','money stewardship finances'],['For the One','Seeing the Person God Has Put in Front of You','Luke 15:1–7','Invite a friend','evangelism easter outreach'],['Come Home','The Father Is Still Waiting for You','Luke 15:11–32','Follow Jesus','gospel salvation grace'],['Raised to Life','What Baptism Says About Your New Story','Romans 6:1–4','Be baptized','baptism obedience'],['This Is Home','Moving From Attending to Belonging','Ephesians 2:19–22','Become a member','membership commitment'],['You and Who?','Who Are You Helping Follow Jesus?','2 Timothy 2:2','Make a disciple','discipleship mentoring'],['Step Up','When God Invites You to Lead','Joshua 1:6–9','Step into leadership','leadership apprentice'],['Teach Us to Pray','Building a Life of Conversation With God','Luke 11:1–4','Pray consistently','prayer'],['Open the Book','Why God’s Word Still Changes Lives','Psalm 119:105','Read Scripture','bible study'],['Live Sent','Seeing Everyday Life as Mission','John 20:21','Live on mission','mission great commission']];
let active='';const el=id=>document.getElementById(id);document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>el(b.dataset.go).scrollIntoView({behavior:'smooth'})));
outcomes.slice(0,10).forEach(x=>{const b=document.createElement('button');b.className='chip';b.textContent=x;b.addEventListener('click',()=>{active=active===x?'':x;document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('on',c.textContent===active));render()});el('chips').appendChild(b)});outcomes.forEach(x=>el('bo').insertAdjacentHTML('beforeend',`<option>${x}</option>`));
function render(){const q=el('q').value.toLowerCase();let r=sermons.filter(s=>(!q||s.join(' ').toLowerCase().includes(q))&&(!active||s[3]===active));if(!r.length)r=sermons.slice(0,4);el('results').innerHTML=r.slice(0,6).map(s=>`<div class="result"><div><h3>${s[0]}</h3><p>${s[1]} · ${s[2]}</p><button class="secondary darkText customize" data-i="${sermons.indexOf(s)}">Customize this sermon</button></div><span class="tag">${s[3]}</span></div>`).join('');document.querySelectorAll('.customize').forEach(b=>b.onclick=()=>{const s=sermons[+b.dataset.i];document.querySelector('[name=theme]').value=s[0];el('bo').value=s[3];el('build').scrollIntoView({behavior:'smooth'})})}
el('searchBtn').onclick=render;render();
el('pf').oninput=()=>{const f=[...el('pf').querySelectorAll('textarea[name]')],n=f.filter(x=>x.value.trim().length>20).length,p=Math.round(n/f.length*100);el('pct').textContent=`Profile ${p}% complete`;el('pb').style.width=p+'%'};el('pf').onsubmit=e=>{e.preventDefault();const f=[...el('pf').querySelectorAll('textarea[name]')],n=f.filter(x=>x.value.trim()).length;el('summary').innerHTML=`<strong>${n}/7 intelligence layers captured.</strong><br>Future recommendations can now be shaped by your theology, voice, church moment, preaching history, priorities and calendar. Keep adding sermons to improve the profile.`};
function visible(o){const m={'Serve in ministry':'Select a ministry, a role and a first serving date.','Join a small group':'Choose a group and register before leaving the service.','Give consistently':'Set a specific regular giving commitment.','Invite a friend':'Name one person and send an invitation this week.','Make a disciple':'Name one person and put the first meeting on the calendar.','Be baptized':'Register for the next baptism opportunity.'};return m[o]||`Take one observable, calendar-based next step toward ${o.toLowerCase()}.`}
function devotional(theme,outcome){const d=[['Sunday','HEAR',`Receive the message: ${theme}. Name the one truth you need to carry into the week.`],['Monday','REFLECT','Re-read the primary text. What does it reveal about God, grace and your present life?'],['Tuesday','PRACTICE',`Take one small, observable action toward ${outcome.toLowerCase()}.`],['Wednesday','TOGETHER','Discuss the message with your Who: a friend, spouse, family member or group.'],['Thursday','SERVE','Ask how this truth can become love expressed for another person.'],['Friday','SHARE','Tell one person what you are learning or invite them into the next step.'],['Saturday','REVIEW','What changed this week? What will you continue? Prepare to bring the learning into Sunday.']];el('devos').innerHTML=d.map(x=>`<div class="day"><small>${x[0]} · ${x[1]}</small><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}
el('bf').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries()),v=d.visible||visible(d.outcome);el('out').innerHTML=`<div class="ey">Sermon intelligence blueprint</div><h3>${d.theme}</h3><div class="summary">Faithful preaching of ${d.theme} should lead toward ${d.outcome.toLowerCase()} through a clear, text-aligned next step.</div><p><strong>Textual integrity:</strong> Confirm the passage's primary meaning before finalizing the outcome. The outcome must come through the text, not be imposed on it.</p><p><strong>Congregational lens:</strong> Apply your profile: where are your people now and what history or readiness matters?</p><p><strong>Video-camera next step:</strong> ${v}</p><p><strong>Gospel connection:</strong> Show how response flows from grace in Christ, not institutional pressure.</p><p><strong>Sticky asset:</strong> Add one testimony, one memorable line and one repeatable practice.</p><p><strong>You + Who?</strong> Name the person or circle with whom the message will be practiced.</p><p><strong>Weekly formation:</strong> This sermon now automatically generates a Sunday-to-Saturday devotional rhythm.</p>`;devotional(d.theme,d.outcome);const a=[['SEE',`Why ${d.theme} Matters`,'Establish the biblical truth and surface the need.'],['START','Take the First Step','Move from agreement to one observable practice.'],['SHARE','Practice It Together','Use groups, families or a You + Who? relationship.'],['MULTIPLY','Pass It On','Help someone else take the same next step.']];el('series').innerHTML=a.map((x,i)=>`<div class="week"><small>WEEK ${i+1} · ${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p><strong>${d.outcome}</strong></div>`).join('');el('devotional').scrollIntoView({behavior:'smooth'})};
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];function calendar(seed=false){const x=seed?[['Prayer + Renewal','Dependence on God'],['Community','Belonging + groups'],['Invitation','Build toward Easter'],['Easter + Gospel','Gospel + baptism'],['Serving + SHAPE','Mobilize ministry'],['Family + Rhythms','Faith at home'],['Wisdom + Rest','Summer formation'],['Vision + Preparation','Prepare fall launch'],['Groups + Growth','Churchwide journey'],['Leadership','Develop multipliers'],['Generosity','Stewardship + gratitude'],['Hope + Mission','Christmas + year-end mission']]:months.map(()=>['Open season','Add a sermon or series priority']);el('planner').innerHTML=months.map((m,i)=>`<div class="month"><small>${m}</small><h3>${x[i][0]}</h3><p>${x[i][1]}</p></div>`).join('')}el('seedBtn').onclick=()=>calendar(true);calendar();